if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.phase0 = fr(1) * 6.2831;          // root-configuration phase offset
  S.aPhase = fr(2) * 6.2831;          // relaxation-orbit phase offset
  S.rot   = (fr(3) - 0.5) * 0.8;      // view rotation
  S.cx0   = (fr(4) - 0.5) * 0.15;     // centre jitter x
  S.cy0   = (fr(5) - 0.5) * 0.15;     // centre jitter y
