const clamp = (v, a, b) => v < a ? a : (v > b ? b : v);
function hsv(h, s, v) { // h deg, s,v 0..1 -> rgb 0..1
  h = ((h % 360) + 360) % 360; const c = v * s, x = c * (1 - Math.abs((h / 60) % 2 - 1)), m = v - c;
  let r, g, b;
