// ---- animated params (read every frame) ----
const style = P.style;
const sec = K.section;
const n = Math.max(2, Math.min(7, Math.round(P.roots)));
const nm1 = n - 1;
const hueSpread = 360 / n;
const hb = P.hue + Math.sin(sec * 0.5 + K.t * 0.015) * 18;                 // gentle section palette drift
const expo = 0.5 + P.energy * 0.6 + K.intensity * 0.25 + A.rms * 0.4;      // exposure builds with intensity
const dens = P.density;
const bandF = 0.6 + dens * 3.5;                                            // contour/band richness
const maxIter = Math.floor(18 + dens * 40 + K.intensity * 16);            // complexity builds with intensity
const tol = 1e-6;

// roots rotate slowly on K.t -> whole basin field swirls (target w = e^{i*psi})
const psi = S.phase0 + K.t * (0.06 + P.speed * 0.05);
