      const v = clamp((0.16 + bright * 0.52 + spec * 0.42) * expo, 0, 1);
      const c = converged ? hsv(hb + kk * 16, 0.16, v) : hsv(hb, 0.1, clamp(0.09 * expo, 0, 0.16));
      r = c[0]; gg = c[1]; b = c[2];
