      const edge = clamp((t01 - 0.42) * 1.95, 0, 1);
      const grid = Math.pow(0.5 + 0.5 * Math.cos(conv * bandF * 1.5), 8);
      const lineI = Math.max(edge, grid * 0.45);
      const nav = 0.10 + 0.05 * bright;
      r = clamp((nav * 0.22 + lineI * 0.16) * expo, 0, 1);
      gg = clamp((nav * 0.55 + lineI * 0.85) * expo, 0, 1);
      b = clamp((nav * 1.05 + lineI * 1.05) * expo, 0, 1);
